// export default MapChart;

import React from "react";
import { MapContainer, TileLayer, Marker, Popup, useMap } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import locationImg from "../../../src/assets/images/location.svg";
import omanFlag from "../../assets/images/Oman-icon.png";
import omanBuildingImg from "../../assets/images/omanBuildingImg.jpg";

// Fix marker icon issue in Leaflet (default icon won't display without this)
import L from "leaflet";
import markerIcon from "leaflet/dist/images/marker-icon.png";
import markerIcon2x from "leaflet/dist/images/marker-icon-2x.png";
import markerShadow from "leaflet/dist/images/marker-shadow.png";
import { Box, Typography } from "@mui/material";

// You can modify the icon as required
L.Icon.Default.mergeOptions({
  iconUrl: markerIcon,
  iconRetinaUrl: markerIcon2x,
  shadowUrl: markerShadow,
});

const MapChart = () => {
  const position = [23.5725, 58.2546]; // Muscat coordinates

  const handleMarkerClick = () => {
    window.open(`https://maps.app.goo.gl/CBW47Gg54mZ6c6Dh8`, "_blank");
  };

  const customIcon = new L.Icon({
    iconUrl: omanFlag, // Custom image URL
    iconSize: [60, 60], // Size of the icon
    iconAnchor: [25, 50], // Anchor point for the icon (bottom-center)
    popupAnchor: [0, -50], // Position of the popup relative to the icon
  });
  const customLabel = new L.divIcon({
    className: "custom-label", // Apply a class to style the label
    html: "<div style='height: 30px; width: 70px; border-radius: 60px; background-color: #FFFFFF; display: flex; align-items: center; justify-content: center;'> <span style='font-size: 16px; font-weight: 400; color: #201D28;'>Oman</span> </div>", // Custom text HTML
    iconSize: [60, 30], // Size of the label (adjust width for the text)
    iconAnchor: [-40, 35], // Position of the label relative to the marker
  });

  return (
    <div
      style={{
        height: "550px",
        width: "100%",
        borderRadius: "12px",
        overflow: "hidden",
        border: "1px solid #602DE1",
      }}
    >
      <MapContainer
        center={position}
        zoom={15} // Adjust zoom for a more detailed view
        style={{ height: "100%", width: "100%" }}
        zoomControl={false}
        attributionControl={false}
      >
        {/* OpenStreetMap basemap with no labels */}
        {/* <TileLayer
          url="https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}.png"
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        /> */}
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        />
        {/* Marker for Muscat */}
        <Marker
          position={position}
          icon={customIcon}
          eventHandlers={{
            mouseover: (e) => {
              e.target.openPopup(); // Open popup on hover
            },
            mouseout: (e) => {
              e.target.closePopup(); // Close popup on mouse out
            },
            click: handleMarkerClick, // Redirect to Google Maps on click
          }}
        >
          <Popup>
            <Box>
              <Typography
                sx={{
                  fontSize: "21px",
                  color: "#201D28",
                  fontWeight: 600,
                  m: 0,
                }}
                style={{ margin: 0 }}
              >
                Muscat
              </Typography>
              <Box sx={{ display: "flex", alignItems: "start", gap: 2, mt: 2 }}>
                <Box sx={{ height: "50px", width: "60px" }}>
                  <img
                    src={omanBuildingImg}
                    alt="Location"
                    style={{ height: "100%", width: "100%" }}
                  />
                </Box>
                <Typography style={{ margin: 0 }}>
                  Gala General Federation of Oman <br />
                  Workers Street 133, First Floor
                </Typography>
              </Box>
            </Box>
          </Popup>
        </Marker>
        <Marker
          position={position}
          icon={customLabel} // Apply custom label
          eventHandlers={{
            mouseover: (e) => {
              e.target.openPopup(); // Open popup on hover
            },
            mouseout: (e) => {
              e.target.closePopup(); // Close popup on mouse out
            },
          }}
        />
      </MapContainer>
    </div>
  );
};

export default MapChart;
